INSERT INTO "PlanItem" ("id", "kind", "title", "description", "status", "area", "priority", "dueDate", "assignee", "createdByName", "updatedAt") VALUES
(gen_random_uuid()::text, 'TASK', 'Юрист: условия продажи для организаций',
'С 06.11 сайт продаёт только организациям и ИП, по счёту. Черновики на сайте: /usloviya (условия продажи) и /garantiya (гарантия и возврат) — закон о защите прав потребителей убран, вместо него ГК и счёт/договор поставки. Вычитать и поправить:
1) применяются ли к такой модели Правила дистанционной торговли (пост. СМ № 31) и нужна ли запись в Торговом реестре (для оптовой торговли);
2) п. 2.4 — договор заключён оплатой счёта; п. 4.2 — передача по ТН/ТТН и доверенности;
3) п. 5 — требования по качеству по ГК, возврат товара надлежащего качества «по согласованию»;
4) п. 6 — претензия, ответ за 15 дней, экономический суд по месту продавца;
5) нужен ли типовой договор поставки на сайте.
Правки текста — разработке (pages/usloviya.vue, pages/garantiya.vue).',
'TODO', 'SALES', 1, '2026-11-20', 'юрист', 'Claude', CURRENT_TIMESTAMP),
(gen_random_uuid()::text, 'TASK', 'Юрист: «первый импортер в РБ» и зачёркнутые цены',
'Фраза «от первого импортера в РБ» стоит в шапке, подвале и на /organizaciyam — по закону о рекламе её надо подтвердить документами или заменить. Зачёркнутая цена берётся из цены «было» у поставщика с нашей наценкой — по ней мы сами не продавали. Решить, оставить ли то и другое.',
'TODO', 'SALES', 2, NULL, 'владелец', 'Claude', CURRENT_TIMESTAMP);
